func TestSendError(t *testing.T) {
	t.Run("writes error frame with message", func(t *testing.T) {
		serverConn, clientConn := net.Pipe()
		defer serverConn.Close()
		defer clientConn.Close()

		s := &session{conn: serverConn}

		var frame duckproxy.ServerFrame
		readErr := make(chan error, 1)
		go func() {
			readErr <- duckproxy.ReadFrame(clientConn, &frame)
		}()

		require.NoError(t, s.sendError(errors.New("boom")))
		require.NoError(t, <-readErr)

		errBody, ok := frame.GetBody().(*duckproxy.ServerFrame_Error)
		require.True(t, ok)
		require.Equal(t, "boom", errBody.Error.Message)
	})

	t.Run("returns error when peer is closed", func(t *testing.T) {
		serverConn, clientConn := net.Pipe()
		clientConn.Close()

		s := &session{conn: serverConn}
		require.Error(t, s.sendError(errors.New("boom")))
		serverConn.Close()
	})
}
